"""Offline named-button editor using the real base texture and declared frames."""
import json
from pathlib import Path


def write_viewer(manifest):
    runtime=(Path(__file__).parent/'title_runtime.js').read_text(encoding='utf-8')
    payload=json.dumps(manifest,ensure_ascii=False).replace('</','<\\/')
    html=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>观窗 · 实际按钮编辑</title><style>
*{box-sizing:border-box}body{margin:0;background:#101a22;color:#e0edf3;font:15px/1.65 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1450px;margin:auto;padding:26px}h1{font-size:25px;margin:0}p{margin:10px 0}.muted{color:#a8bdc9}.notice{color:#f2cb84}.grid{display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:20px;margin-top:22px}.card{background:#1b2b37;border:1px solid #354e5f;padding:18px;border-radius:8px}.rowpreview{overflow:auto;background:#0c151c;padding:24px 10px;border:1px solid #344c5b;min-height:110px}.row{display:flex;align-items:flex-start;width:max-content;gap:12px}.sibling{border:1px solid #587184;color:#a9bdc8;text-align:center;background:#203543;font-size:14px;flex:none;overflow:hidden}canvas{display:block;cursor:pointer;border:1px solid #b5e9d4;box-sizing:content-box}label{display:block;margin:10px 0}input,button,select{font:inherit}input,select{width:100%;background:#0c1a23;color:#e6f0f3;border:1px solid #56778b;border-radius:5px;padding:8px}button{padding:9px 13px;border:0;border-radius:5px;background:#a2deca;color:#15352e;cursor:pointer;margin:5px 5px 5px 0}button.secondary{background:#36556a;color:#dfedf3}.dims{display:grid;grid-template-columns:1fr 1fr;gap:12px}pre{font:12px/1.6 monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#0c1720;padding:12px;border-radius:5px}.status{color:#ace2cb;min-height:45px}.error{color:#ffb3a6}.file{font-size:13px}code{overflow-wrap:anywhere}#selected{margin:16px 0;font-size:13px;color:#a8e7db}@media(max-width:950px){.grid{grid-template-columns:1fr}}</style></head><body><main>
<h1>观窗 · 军府真实按钮编辑</h1><p class="muted">当前按钮：<strong id="buttonName"></strong> · 文字与显式宽高可编辑，条件和点击动作保留。</p><p class="notice">预览使用实际DDS基础纹理与源码声明的帧；叠加材质、shader和字体尚未完整还原，状态为手动模拟，不代表游戏当前状态。</p>
<div class="grid"><section><div class="card"><strong>所属按钮横排 · 尺寸示意</strong><p class="muted file">调整宽度会移动同一横排的后续按钮。点击目标只选择控件，不执行游戏操作。</p><div class="rowpreview"><div id="row" class="row"></div></div><div id="selected"></div><p id="layout" class="notice file"></p><label>模拟按钮状态<select id="state"><option value="normal">正常</option><option value="hover">悬停</option><option value="pressed">按下</option><option value="selected">选中</option><option value="disabled">禁用</option></select></label></div><h3>本次源码修改</h3><pre id="diff"></pre><details open><summary>保留的按钮逻辑</summary><pre id="logic"></pre></details><details><summary>类型、模板、资源来源</summary><pre id="provenance"></pre></details></section>
<aside class="card"><label>按钮文字<input id="text" type="text"></label><div class="dims"><label>宽度<input id="width" type="number" min="1" max="65536" step="1"></label><label>高度<input id="height" type="number" min="1" max="65536" step="1"></label></div><button id="reset" class="secondary">恢复导入值</button><button id="export">导出完整GUI草稿</button><button id="request" class="secondary">导出编辑请求</button><button id="receipt" class="secondary">导出校验记录</button><label class="file">回读刚导出的GUI<input id="reimport" type="file" accept=".gui"></label><div id="status" class="status" role="status"></div><p class="muted file">只改常量文字和size中的两个数值。导出文件不会自动安装，所有点击回调、条件和其它源码保持。</p><pre id="identity"></pre></aside></div>
</main><script id="manifest" type="application/json">__DATA__</script><script>__RUNTIME__</script><script>
const M=JSON.parse(document.getElementById('manifest').textContent),G=GuanchuangTitle,$=id=>document.getElementById(id);let revision=0,result=null,pending=null,images={};
function status(s,error=false){$('status').textContent=s;$('status').className='status'+(error?' error':'')}
function changes(){const values={raw_text:$('text').value,width:Number($('width').value),height:Number($('height').value)};G.literal(values.raw_text);G.dimension(values.width);G.dimension(values.height);return Object.fromEntries(Object.entries(values).filter(([k,v])=>v!==M.fields[k].value))}
function band(context,image,sx,sy,sw,sh,dx,dy,dw,dh){if(!sw||!sh||!dw||!dh)return;for(let yy=0;yy<dh;yy+=sh)for(let xx=0;xx<dw;xx+=sw){const w=Math.min(sw,dw-xx),h=Math.min(sh,dh-yy);context.drawImage(image,sx,sy,w,h,dx+xx,dy+yy,w,h)}}
function skin(canvas,w,h){canvas.width=w;canvas.height=h;const c=canvas.getContext('2d'),im=images[$('state').value];if(im){const [fw,fh]=M.reference.base_texture.frame_size;const border=M.reference.properties.spriteborder.value||[0,0],bx=Math.max(0,Math.min(Number(border[0]),Math.floor(w/2),Math.floor(fw/2))),by=Math.max(0,Math.min(Number(border[1]),Math.floor(h/2),Math.floor(fh/2)));const sx=[0,bx,fw-bx],sy=[0,by,fh-by],sw=[bx,fw-bx*2,bx],sh=[by,fh-by*2,by],dx=[0,bx,w-bx],dy=[0,by,h-by],dw=[bx,w-bx*2,bx],dh=[by,h-by*2,by];for(let y=0;y<3;y++)for(let x=0;x<3;x++)band(c,im,sx[x],sy[y],sw[x],sh[y],dx[x],dy[y],dw[x],dh[y])}else{c.fillStyle='#2c495a';c.fillRect(0,0,w,h)}c.fillStyle='#e7cc8b';c.font='15px Microsoft YaHei,system-ui,sans-serif';c.textAlign='center';c.textBaseline='middle';c.save();c.beginPath();c.rect(4,0,Math.max(0,w-8),h);c.clip();c.fillText($('text').value,w/2,h/2);c.restore()}
function draw(){
 const w=Number($('width').value),h=Number($('height').value),container=$('row');
 container.replaceChildren();container.style.gap=M.preview.spacing+'px';
 let x=0,following=false,effects=[];
 for(const s of M.preview.row){
  const el=document.createElement(s.target?'canvas':'div'),width=s.target?w:s.width,height=s.target?h:s.height;
  el.style.width=width+'px';el.style.height=height+'px';el.style.flex='none';
  if(s.target){
   el.id='buttonPreview';el.onclick=()=>{$('selected').textContent='已选择 '+M.button_name+'；点击回调保持原文，不在页面执行。'};
   skin(el,Math.min(w,2048),Math.min(h,512));following=true;
  }else{el.className='sibling';el.textContent=s.label;if(following)effects.push((s.name||s.label)+': X='+x)}
  container.appendChild(el);x+=width+M.preview.spacing;
 }
 $('layout').textContent=`当前横排合计 ${x-M.preview.spacing} / 源声明 ${M.preview.row_width} UI单位。后续按钮 ${effects.join('；')||'无'}。仅尺寸模型，原生布局尚未校准。`+(w>2048||h>512?' 超大尺寸仅缩放示意，导出尺寸不变。':'');
 document.body.dataset.simulatedState=$('state').value;
}
async function refresh(){const v=++revision;result=null;try{const c=changes();draw();$('diff').textContent=Object.keys(c).length?Object.entries(c).map(([k,n])=>`${k}: ${JSON.stringify(M.fields[k].value)} → ${JSON.stringify(n)}`).join('\n'):'尚未修改，导出与导入GUI逐字节相同。';const r=await G.apply(M,G.request(M,c));if(v!==revision)return;result=r;status(`草稿准备完成：${r.receipt.patches.length}处token变化，其余字节保留。`);document.body.dataset.ready='1';document.body.dataset.patchCount=String(r.receipt.patches.length)}catch(e){if(v===revision)status(e.message,true)}}
function update(){pending=refresh();return pending}async function current(){await pending;if(!result)throw new Error('请先修正输入值');return result}
function download(name,blob){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}function jsonSave(name,value){download(name,new Blob([JSON.stringify(value,null,2)],{type:'application/json;charset=utf-8'}))}
for(const[k,id]of Object.entries({raw_text:'text',width:'width',height:'height'})){$(id).value=String(M.fields[k].value);$(id).oninput=update}
$('state').onchange=update;$('reset').onclick=()=>{for(const[k,id]of Object.entries({raw_text:'text',width:'width',height:'height'}))$(id).value=String(M.fields[k].value);return update()};
$('buttonName').textContent=M.button_name;$('logic').textContent=M.protected_statements.map(s=>s.key+' = '+(s.value===null?s.body:s.value)).join('\n');$('identity').textContent=JSON.stringify({source:M.source,line:M.owner_line,owner_id:M.owner_id,base_sha256:M.base_sha256},null,2);$('provenance').textContent=JSON.stringify(M.reference?{status:M.reference.status,properties:M.reference.properties,definitions:M.reference.definitions,assets:M.reference.assets,issues:M.reference.resolver_issues,render_limit:M.reference.render_limit}:null,null,2);
$('export').onclick=async()=>{try{const r=await current();download(M.source.split('/').pop(),new Blob([r.bytes],{type:'application/octet-stream'}));status('完整GUI草稿已交给浏览器保存；未写安装目录。')}catch(e){status(e.message,true)}};$('request').onclick=async()=>{try{jsonSave('button-edit-request.json',(await current()).request)}catch(e){status(e.message,true)}};$('receipt').onclick=async()=>{try{jsonSave('button-edit-receipt.json',(await current()).receipt)}catch(e){status(e.message,true)}};
$('reimport').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const raw=new Uint8Array(await f.arrayBuffer()),r=await current();if(!G.equal(raw,r.bytes))throw new Error('回读文件不等于当前草稿');status('回读字节一致；完整解析与游戏效果须另行验证。');document.body.dataset.reimport='PASS'}catch(e){status(e.message,true);document.body.dataset.reimport='FAIL'}};
const ready=M.reference?Promise.all(Object.entries(M.reference.base_texture.states).map(([s,data])=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images[s]=im;resolve()};im.onerror=()=>reject(new Error('纹理帧加载失败'));im.src='data:image/png;base64,'+data.png_base64}))):Promise.resolve();pending=ready.then(update).catch(e=>status(e.message,true));
</script></body></html>'''
    return html.replace('__RUNTIME__',runtime).replace('__DATA__',payload)
